INSERT INTO `course` VALUES
(1,'ISTE 230','None','Fall 2013',0x00,'3','The course provides foundational knowledge in database concepts, including the process of data modeling, the principles of the relational database model, normalization, and relational algebra.',0x00,'ISTE',0x00,'June 2019','Introduction to Database and Data Modeling',0x00,'ISTE-120 or ISTE-200 or CSCI-140 or CSCI-142 or equivalent course.',0x01,1),
(2,'GCIS 123','None','Fall 2013',0x00,'4','This course focuses on algorithmic thinking, computational problem-solving, and applying these concepts to design and implement software solutions. Key topics include algorithmic thinking, object-oriented programming in Python, fundamental software engineering principles, and team-based work with distributed version control. ',0x00,'GCIS',0x00,'June 2024','Software Development and Problem Solving I',0x00,'None',0x01,1),
(3,'NSSA 102','None','Fall 2013',0x00,'3','This course teaches the student the essential technologies needed by NSSA majors, focused on PC and mainframe hardware topics. They include how those platforms operate, how they are configured, and the operation of their major internal components. ',0x00,'NSSA',0x00,'May 2019','Computer System Concepts',0x00,'None',0x01,1),
(4,'GCIS 124','None','June 2020',0x00,'4','A second course that delves further into computational problem solving, now with a focus on an object-oriented perspective. There is a continued emphasis on basic software design, testing & verification, and incremental development',0x00,'GCIS',0x00,'Dec 2022','Software Development and Problem Solving II',0x00,'C- or better in GCIS-123 or CSEC-123 or ISTE-123 or equivalent course.',0x01,1),
(5,'ISTE 140','None','Fall 2013',0x00,'3','This course provides students with an introduction to Internet and Web technologies, and to development on Macintosh/UNIX computer platforms. opics include HTML and CSS, CSS3 features, digital images, Web page design and Web site publishing.',0x00,'ISTE',0x00,'July 2019','Web & Mobile I',0x00,'None',0x01,1),
(6,'NSSA 241','None','Fall 2013',0x00,'3','This course provides an introduction to wired network infrastructures, topologies, technologies, and the protocols required for effective end-to-end communication. Basic security concepts for TCP/IP based technologies are introduced.',0x00,'NSSA',0x00,'July 2022','Introduction to Routing & Switching',0x00,'NSSA-102 or CSEC-101 or CACT-151 or CSCI-250',0x01,1),
(7,'NSSA 220','None','Unlisted',0x00,'3','An introduction to the Unix operating system and scripting in the Perl and Unix shell languages. The course will cover basic user-level commands to the Unix operating system, followed by basic control structures, and data structures in Perl.',0x00,'NSSA',0x00,'August 2022','Task Automation with Interpreted Languages',0x00,'GCIS-124',0x01,1),
(8,'ISTE 240','None','Fall 2013',0x00,'3','This course builds on the basics of web page development that are presented in ISTE 140 and extends that knowledge to focus on theories, issues, and technologies related to the design and development of web sites.',0x00,'ISTE',0x00,'July 2019','Web & Mobile II',0x00,'ISTE-140',0x01,1),
(9,'NSSA 221','None','Fall 2013',0x00,'3','This course is designed to give students an understanding of the role of the system administrator in large organizations. This will be accomplished through a discussion of many of the tasks and tools of system administration.',0x01,'NSSA',0x00,'July 2019','System Administration I',0x00,'(NSSA-220 or CSCI-141) and NSSA-241',0x01,1),
(10,'SWEN 261','None','June 2022',0x00,'3','An introductory course in software engineering, emphasizing the organizational aspects of software development and software design and implementation by individuals and small teams within a process/product framework.',0x00,'SWEN',0x00,'June 2022','Introduction to Software Engineering',0x00,'CSCI-140 or CSCI-142 or CSCI-242 or SWEN-124 or CSEC-124 or GCIS-124 or equivalent course.',0x01,2),
(11,'ISTE 260','None','Fall 2013',0x00,'3','The user experience is an important design element in the development of interactive systems. This course presents the foundations of user-centered design principles within the context of human-computer interaction (HCI).',0x00,'ISTE',0x00,'July 2019','Designing the User Experience',0x00,'ISTE-140 or IGME-230 or NACA-172 or equivalent course.',0x01,2),
(12,'ISTE 470','None','Feb 2018',0x00,'3','Rapidly expanding volumes of data from all areas of society are becoming available in digital form. High value information and knowledge is embedded in many of these data volumes.',0x00,'ISTE',0x00,'August 2020','Data Mining & Exploration',0x00,'(STAT-145 OR MATH- 251) and (GCIS-124 OR ISTE-121 OR CSCI- 140 OR CSCI-142 OR CSCI-242 OR ISTE-200 OR IGME-201 OR IGME-106) or equivalent courses',0x01,2),
(13,'ISTE 330','None','Fall 2013',0x00,'3','In this course, students will build applications that interact with databases. Through programming exercises, students will work with multiple databases and programmatically invoke the advanced database processing operations that are integral to contemporary computing applications. ',0x00,'ISTE',0x00,'July 2019','Database Connectivity & Access',0x00,'(ISTE-230 or CSCI-320) and (ISTE-120 or GCIS-124 or CSCI-140 or CSCI-142 or CSCI-242) or equivalent courses.',0x01,2),
(14,'ISTE 430','None','Fall 2013',0x00,'3','Students will survey and apply contemporary techniques used in analyzing and modeling information requirements. Requirements will be elicited in a variety of domains and abstracted at conceptual, logical, and physical levels of detail.',0x00,'ISTE',0x00,'July 2019','Information Requirements Modeling',0x00,'ISTE-230 or CSCI-320 or equivalent course',0x01,2),
(15,'NSSA 245','None','Fall 2013',0x00,'3','This course will investigate the protocols used to support network-based services and the tasks involved in configuring and administering those services in virtualized Linux and Windows internetworking environments.',0x01,'NSSA',0x00,'Dec 2023','Network Services',0x00,'NSSA-241 and (NSSA-220 or CSCI- 141 or GCIS-123) and NSSA-221 or equivalent courses',0x01,2),
(16,'NSSA 443','None','Fall 2013',0x00,'3','This course will examine the design and performance of networks. Students will learn to design networks based on identified needs and analyze the performance of that network.',0x01,'NSSA',0x00,'May 2020','Network Design & Performance',0x00,'NSSA-241',0x01,2),
(17,'ISTE 340','None','August 2024',0x00,'3','This course will explore the analysis, design, development, and implementation of client-side programming in the context of Internet technologies, mobile devices, Web-based client systems and desktop applications.',0x00,'ISTE',0x00,'October 2024','Client Programming',0x00,'(ISTE-240 or IGME-330) and (GCIS-124 or ISTE-121 or ISTE-200 or CSCI-142 or CSCI- 140 or IGME-106 or IGME-102 or GCIS-127) or equivalent courses.',0x01,2),
(18,'ISTE 500','None','Fall 2013',0x00,'3','The first course in a two-course, senior level, system development capstone project. Students form project teams and work with sponsors to define system requirements.',0x01,'ISTE',0x00,'July 2019','Senior Development Project I',0x00,'The completion of 2 co-ops is required',0x01,2),
(19,'IGME 101','None','Fall 2013',0x00,'4','This course provides students with an introduction to problem solving, abstraction, and algorithmic thinking that is relevant across the field of new media.',0x00,'IGME',0x00,'July 2019','New Media Interactive Design and Algorithmic Problem Solving I',0x00,'None',0x01,2),
(20,'CSEC 201','None','Fall 2013',0x00,'3','This course builds upon basic programming skills to give students the programming knowledge necessary to study computing security. Students will be introduced to network programming, memory management, and operating system calls along with associated security concepts.',0x00,'CSEC',0x00,'July 2019','Programming for Information Security',0x00,'CSEC-101 or CSEC-140) and (CSCI-142 or GCIS-124 or GCIS-127 or CSCI-242) or equivalent courses.',0x01,2),
(21,'CSEC 140','None','Fall 2013',0x00,'3','The course will teach students to think about information systems using an adversarial mindset, evaluate risk to information systems, and introduce controls that can be implemented to reduce risk.',0x00,'CSEC',0x00,'July 2019','Introduction to Cybersecurity',0x00,'None',0x01,2),
(22,'CSEC 790','None','Fall 2013',0x00,'3','This course is one of the capstone options in the MS in Cybersecurity program. It offers students the opportunity to investigate a selected topic and make an original contribution which extends knowledge within the Cybersecurity domain. ',0x00,'CSEC',0x00,'July 2019','MS Thesis',0x00,'None',0x01,2),
(23,'ISTE 436','None','Spring 2018',0x00,'3','Students will be introduced to issues in client/server database implementation and administration. Students will\nconfigure, test, and establish client-server communication and server-server communication with single and\nmultiple database servers.',0x00,'ISTE',0x00,'August 2020','Database Management and Access',0x00,'ISTE-230',0x01,2),
(24,'CSEC 900','None','Fall 2013',0x00,'3','This course is one of the capstone options in the MS in Cybersecurity program. Students will apply their knowledge to solve real-world problems in the areas of Cybersecurity.',0x00,'CSEC',0x00,'August 2020','Continuation of Thesis',0x00,'None',0x01,2);
