INSERT INTO `plo` VALUES
(1,'Analyze a complex computing problem and to apply principles of computing and other relevant disciplines to identify solutions.','Problem Solving',1,'a'),
(2,'Design, implement, and evaluate a computing-based solution to meet a given set of computing requirements in the context of the program’s disciplines.','System Design',1,'b'),
(3,'Communicate effectively in a variety of professional contexts.','Communication',1,'c'),
(4,'Recognize professional responsibilities and make informed judgments in computing practice based on legal and ethical principles.','Professional Responsibility and Ethics',1,'d'),
(5,'Function effectively as a member or leader of a team engaged in activities appropriate to the program’s discipline.','Teamwork',1,'e'),
(6,'Identify and analyze user needs and to take them into account in the selection, creation, integration, evaluation, and administration of computing-based systems.','System Requirement Analysis',1,'f');
