n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"c57\">\n                        <p class=\"c46\">\n                  <span class=\"c2\">Quiz 5</span>\n                        </p>\n                    </td>\n                    <td class=\"c47\">\n                        <p class=\"c35\">\n    <span class=\"c2\">\n      \n    </span>\n                        </p>\n                    </td>\n                    <td class=\"c44\">\n                        <p class=\"c32\">\n                  <span class=\"c2\">5</span>\n                        </p>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"c57\">\n                        <p class=\"c46\">\n                  <span class=\"c2\">Assignment 1</span>\n                        </p>\n                    </td>\n                    <td class=\"c47\">\n                        <p class=\"c35\">\n    <span class=\"c2\">\n      \n    </span>\n                        </p>\n                    </td>\n                    <td class=\"c44\">\n                        <p class=\"c32\">\n                  <span class=\"c2\">10</span>\n                        </p>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"c57\">\n                        <p class=\"c46\">\n                  <span class=\"c2\">Assignment 2</span>\n                        </p>\n                    </td>\n                    <td class=\"c47\">\n                        <p class=\"c35\">\n    <span class=\"c2\">\n      \n    </span>\n                        </p>\n                    </td>\n                    <td class=\"c44\">\n                        <p class=\"c32\">\n                  <span class=\"c2\">10</span>\n                        </p>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"c57\">\n                        <p class=\"c46\">\n                  <span class=\"c2\">Midterm</span>\n                        </p>\n                    </td>\n                    <td class=\"c47\">\n                        <p class=\"c35\">\n    <span class=\"c2\">\n      \n    </span>\n                        </p>\n                    </td>\n                    <td class=\"c44\">\n                        <p class=\"c32\">\n                  <span class=\"c2\">25</span>\n                        </p>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"c57\">\n                        <p class=\"c46\">\n                  <span class=\"c2\">Final</span>\n                        </p>\n                    </td>\n                    <td class=\"c47\">\n                        <p class=\"c35\">\n    <span class=\"c2\">\n      \n    </span>\n                        </p>\n                    </td>\n                    <td class=\"c44\">\n                        <p class=\"c32\">\n                  <span class=\"c2\">30</span>\n                        </p>\n                    </td>\n                </tr>\n                <tr class=\"c93\">\n                    <td class=\"c131\" colspan=\"2\">\n                        <p class=\"c32\"><span class=\"c15 c3\">Total</span></p>\n                    </td>\n                    <td class=\"c44\">\n                        <p class=\"c32\"><span class=\"c15 c3\">100%</span></p>\n                    </td>\n                </tr>\n            </table>\n            <p class=\"c27 c41\"><span class=\"c2\"></span></p>\n        </td>\n    </tr>\n</table>\n\n<!-- Description of Assessments -->\n<h1 class=\"c102\">\n    <span class=\"c28 c11 c13\">Description of Assessments: </span>\n</h1>\n<!-- Category descriptions rendered from the service -->\n\n\n<p class=\"c37 c27 c49\"><span class=\"c2\"></span></p>\n<p class=\"c53 c49\">\n      <span class=\"c3\"></span>\n    <span class=\"c13\"></span>\n</p>\n<p class=\"c53 c49\">\n      <span sty