             <td class=\"c57\">\n                        <p class=\"c46\">\n                  <span class=\"c2\">Quiz 5</span>\n                        </p>\n                    </td>\n                    <td class=\"c47\">\n                        <p class=\"c35\">\n    <span class=\"c2\">\n      \n    </span>\n                        </p>\n                    </td>\n                    <td class=\"c44\">\n                        <p class=\"c32\">\n                  <span class=\"c2\">5</span>\n                        </p>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"c57\">\n                        <p class=\"c46\">\n                  <span class=\"c2\">Midterm</span>\n                        </p>\n                    </td>\n                    <td class=\"c47\">\n                        <p class=\"c35\">\n    <span class=\"c2\">\n      \n    </span>\n                        </p>\n                    </td>\n                    <td class=\"c44\">\n                        <p class=\"c32\">\n                  <span class=\"c2\">25</span>\n                        </p>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"c57\">\n                        <p class=\"c46\">\n                  <span class=\"c2\">Final</span>\n                        </p>\n                    </td>\n                    <td class=\"c47\">\n                        <p class=\"c35\">\n    <span class=\"c2\">\n      \n    </span>\n                        </p>\n                    </td>\n                    <td class=\"c44\">\n                        <p class=\"c32\">\n                  <span class=\"c2\">30</span>\n                        </p>\n                    </td>\n                </tr>\n                <tr>\n                    <td class=\"c57\">\n                        <p class=\"c46\">\n                  <span class=\"c2\">Project</span>\n                        </p>\n         