e a nested loop. Here’s one method using a nested loop. -->\n        <td class=\"c51\">\n            <h1 class=\"c23\">\n        <span>Final</span>\n            </h1>\n        </td>\n    </tr>\n    </tbody>\n</table>\n    <tr class=\"c138\">\n        <td class=\"c30 c59\">\n            <h1 class=\"c12\"><span class=\"c2\"></span></h1>\n        </td>\n        <td class=\"c59 c98\" colspan=\"3\">\n            <h1 class=\"c63\">\n                <span class=\"c34\"></span>\n            </h1>\n        </td>\n    </tr>\n</table>\n<h1 class=\"c12\"><span class=\"c28 c11 c13\"></span></h1>\n\n<!-- Course Policies and Attendance -->\n<h1 class=\"c23 c60\">\n    <span class=\"c28 c11 c13\">Course Policies:</span>\n</h1>\n<p class=\"c37 c60\">\n    <span class=\"c45 c43\">Classroom conduct</span>\n</p>\n<ul class=\"c31 lst-kix_list_1-0 start\">\n    <li class=\"c53 c119 c60 li-bullet-0\">\n        <span class=\"c13\">\n          The rules of decorum apply in class: be respectful of me and of peers, ask productive questions, make appropriate and helpful observations…\n        </span>\n    </li>\n    <li class=\"c58 li-bullet-0\">\n        <span class=\"c13\">\n          Electronic devices—mobiles, tablets, and laptops—must be off and put away during class unless used for a specific activity.\n        </span>\n    </li>\n    <li class=\"c58 li-bullet-0\">\n        <span class=\"c13\">\n          No naps, no snacks. If you are too tired or hungry, take the absence.\n        </span>\n    </li>\n    <li class=\"c94 li-bullet-0\">\n        <span class=\"c2\">\n          If you work consistently and conscientiously, I will “round up” the “ones” before posting final grades.\n        </span>\n    </li>\n</ul>\n<p class=\"c37\">\n    <span class=\"c2\">Infractions of these rules of conduct will negatively impact your final grade.</span>\n</p>\n<p class=\"c37 c60\">\n    <span class=\"c71 c45 c74 c43 c13 c108\">Course Management</span>\n</p>\n<ul class=\"c31 lst-kix_list_1-0\">\n    <li class=\"c58 c60 li-bullet-0\">\n        <span class=\"c13\">\n          You are responsible for knowing what’s due and when by referring to the syllabus.\n        </span>\n    </li>\n    <li class=\"c58 li-bullet-0\">\n        <span class=\"c13\">\n          Coursework is cumulative—complete them conscientiously.\n        </span>\n    </li>\n    <li class=\"c58 li-bullet-0\">\n        <span class=\"c3\">Type-written work</span><span class=\"c2\"> must be turned in through MyCourses and in hard copy by the fixed deadlines.</span>\n    </li>\n    <li class=\"c58 li-bullet-0\">\n        <span class=\"c13\">\n          Individual work must be your own.\n        </span>\n    </li>\n    <li class=\"c58 li-bullet-0\">\n        <span class=\"c3\">Late work</span><span class=\"c2\"> will be deducted 10% every calendar day without exception.</span>\n    </li>\n    <li class=\"c94 li-bullet-0\">\n        <span class=\"c3\">Things may change</span> <span class=\"c13\">but such changes will be communicated in writing.</span>\n    </li>\n</ul>\n<p class=\"c37 c60\">\n    <span class=\"c45 c43\">Attendance Policy:</span>\n</p>\n<p class=\"c37 c60\">\n    <span class=\"c3 c15\">Please select one of these two options:</span>\n</p>\n<!-- Show one of the two options based on a Boolean variable -->\n\n\n<ul class=\"c31 lst-kix_list_5-0\">\n    <li class=\"c53 c133 li-bullet-0\">\n        <span class=\"c15 c3\">Attendance is not mandatory for this course</span>\n    </li>\n</ul>\n<p class=\"c37 c100\">\n      <span class=\"c71 c74 c43 c13 c96\">\n        (If you chose not to apply the attendance policy, then you must clearly state the following here in the syllabus and attendance record is not applicable in this case.)\n      </span>\n</p>\n<p class=\"c53 c83\">\n      <span class=\"c2\"></span>\n</p>\n<p class=\"c53 c83\">\n    <span class=\"c2\">Refer to university policy 3.1.14-B.</span>\n</p>\n\n<!-- RIT Dubai Honor Principles and Academic Integrity -->\n<p class=\"c23\">\n    <span class=\"c28 c11 c13\">RIT Dubai Honor Principles:</span>\n</p>\n<p class=\"c53 c65\">\n      <span class=\"c13 c125\">\n        Refer to Policy 5.1.1- RIT Dubai Honor Code in the Student Handbook\n      </span>\n</p>\n<h1 class=\"c37\">\n    <span class=\"c28 c11 c13\">Academic Integrity:</span>\n</h1>\n<p class=\"c53 c70\">\n      <span class=\"c125\"></span>\n</p>\n<p class=\"c53 c70\">\n      <span></span>\n</p>\n<p class=\"c53 c70\">\n      <span></span>\n</p>\n<p class=\"c53 c70\">\n      <span></span>\n</p>\n<p class=\"c53 c70\">\n    <span class=\"c28 c50 c13\">Procedures for handling Academic Dishonesty:</span>\n</p>\n<p class=\"c53 c70\" id=\"h.30j0zll\">\n      <span class=\"c125\"></span>\n</p>\n<p class=\"c27 c105\"><span class=\"c0\"></span></p>\n</body>\n','2026-05-01',0x01,25),
(212,'\n<body class=\"c78 c137 doc-content\">\n<div>\n    <p class=\"c27 c106\"><span class=\"c2\"></span></p>\n    <p class=\"c91\"><span class=\"c2\">ISTE 430</span></p>\n</div>\n<p class=\"c22 title\"><span style=\"overflow: hidden; display: inline-block; margin: 0.00px 0.00px; border: 0.00px solid #000000; transform: rotate(0.00rad) translateZ(0px); -webkit-transform: rotate(0.00rad) translateZ(0px); width: 698.00px; height: 129.60px;\"><img alt=\"Logo.jpg\" src=\"/static/images/logo.jpg\" style=\"width: 698.00px; height: 129.60px; margin-left: -0.00px; margin-top: -0.00px; transform: rotate(0.00rad) translateZ(0px); -webkit-transform: rotate(0.00rad) translateZ(0px);\" title=\"\"></span></p>\n<!--<img th:src=\"@{/images/logo.jpg}\" alt=\"Image Description\" />-->\n\n<!-- Header: Course Title and Schedule -->\n<p class=\"c22 title\">\n      <span class=\"c11 c74\">ISTE 430: Information Requirements Modeling</span><br>\n    <span class=\"c28 c45 c13 c71\">MW 4:05 - 5:25 : Room B211</span>\n</p>\n\n<!-- Instructor and course basic info table -->\n<table class=\"c20\">\n    <tr class=\"c24\">\n        <td class=\"c61 c59\">\n            <p class=\"c22\"><span class=\"c15 c3\">Instructor</span></p>\n        </td>\n        <td class=\"c59 c116\">\n            <p class=\"c22\"><span class=\"c15 c3\">Office</span></p>\n        </td>\n        <td class=\"c81 c59\">\n            <p class=\"c22\"><span class=\"c15 c3\">Phone</span></p>\n        </td>\n        <td class=\"c59 c72\">\n            <p class=\"c22\"><span class=\"c15 c3\">Email</span></p>\n        </td>\n        <td class=\"c76 c59\">\n            <p class=\"c22\"><span class=\"c15 c3\">Semester-Year</span></p>\n        </td>\n    </tr>\n    <tr class=\"c24\">\n        <td class=\"c61\">\n            <p class=\"c22\">\n                <span class=\"c2\">Khalil Al Hussaeni</span>\n            </p>\n        </td>\n        <td class=\"c116\">\n            <p class=\"c22\">\n                <span class=\"c2\">D004</span>\n            </p>\n        </td>\n        <td class=\"c81\">\n            <p class=\"c22\">\n                <span class=\"c2\">3712</span>\n            </p>\n        </td>\n        <td class=\"c72\">\n            <p class=\"c22\">\n                <span class=\"c2\">jk8835@g.rit.edu</span>\n            </p>\n        </td>\n        <td class=\"c76\">\n            <p class=\"c22\">\n                <span class=\"c2\">Spring 2026</span>\n            </p>\n        </td>\n    </tr>\n    <tr class=\"c24\">\n        <td class=\"c61\">\n            <p class=\"c22\">\n                <span class=\"c15 c3\">Office Hours:</span>\n            </p>\n        </td>\n        <td class=\"c111\" colspan=\"4\">\n            <p class=\"c37\">\n            <span class=\"c2\">TueThu: 12:00pm - 1:30pm</span>\n            </p>\n        </td>\n    </tr>\n</table>\n<p class=\"c37 c27\"><span class=\"c2\"></span></p>\n\n<!-- Course details table -->\n<table class=\"c20\">\n    <tr class=\"c24\">\n        <td class=\"c73\" rowspan=\"2\">\n            <p class=\"c37\"><span class=\"c15 c3\">Discipline:</span></p>\n        </td>\n        <td class=\"c80\" rowspan=\"2\">\n            <p class=\"c37\">\n                <span class=\"c2\">ISTE</span>\n            </p>\n        </td>\n        <td class=\"c104\" colspan=\"5\">\n            <p class=\"c37\"><span class=\"c15 c3\">Course Approval Date:</span></p>\n        </td>\n        <td class=\"c113\" colspan=\"2\">\n            <p class=\"c37\">\n                <span class=\"c2\">Fall 2013</span>\n            </p>\n        </td>\n    </tr>\n    <tr class=\"c24\">\n        <td class=\"c104\" colspan=\"5\">\n            <p class=\"c37\"><span class=\"c15 c3\">Last Revision Date</span></p>\n        </td>\n        <td class=\"c113\" colspan=\"2\">\n            <p class=\"c37\">\n                <span class=\"c2\">July 2019</span>\n            </p>\n        </td>\n    </tr>\n    <tr class=\"c24\">\n        <td class=\"c73\">\n            <p class=\"c37\"><span class=\"c15 c3\">Course Number:</span></p>\n        </td>\n        <td class=\"c64\">\n            <p class=\"c37\">\n                <span class=\"c2\">ISTE 430</span>\n            </p>\n        </td>\n        <td class=\"c85\" colspan=\"2\">\n            <p class=\"c37\"><span class=\"c15 c3\">Course Title:</span></p>\n        </td>\n        <td class=\"c62\" colspan=\"7\">\n            <p class=\"c37\">\n                <span class=\"c2\">Information Requirements Modeling</span>\n            </p>\n        </td>\n    </tr>\n    <tr class=\"c24\">\n        <td class=\"c73\">\n            <p class=\"c37\"><span class=\"c15 c3\">Undergraduate:</span></p>\n        </td>\n        <td class=\"c64\">\n            <p class=\"c37\">\n                <span class=\"c2\">Yes</span>\n            </p>\n        </td>\n        <td class=\"c85\" colspan=\"2\">\n            <p class=\"c37\"><span class=\"c15 c3\">New Course:</span></p>\n        </td>\n        <td class=\"c90\">\n            <p class=\"c37\">\n                <span class=\"c2\">No</span>\n            </p>\n        </td>\n        <td class=\"c115\" colspan=\"3\">\n            <p class=\"c37\"><span class=\"c15 c3\">Course Deletion:</span></p>\n        </td>\n        <td class=\"c8\">\n            <p class=\"c37\">\n                <span class=\"c2\"></span>\n            </p>\n        </td>\n        <td class=\"c17\">\n            <p class=\"c37\"><span class=\"c15 c3\">Credits:</span></p>\n        </td>\n        <td class=\"c7\">\n            <p class=\"c37\">\n                <span class=\"c2\">3</span>\n            </p>\n        </td>\n    </tr>\n    <tr class=\"c24\">\n        <td class=\"c73\">\n            <p class=\"c37\"><span class=\"c15 c3\">Graduate:</span></p>\n        </td>\n        <td class=\"c64\">\n            <p class=\"c37\">\n                <span class=\"c2\">No</span>\n            </p>\n        </td>\n        <td class=\"c85\" colspan=\"2\">\n            <p class=\"c37\"><span class=\"c15 c3\">Prerequisites:</span></p>\n        </td>\n        <td class=\"c112\" colspan=\"2\">\n            <p class=\"c37\">\n                <span class=\"c2\">ISTE-230 or CSCI-320 or equivalent course</span>\n            </p>\n        </td>\n        <td class=\"c55\">\n            <p class=\"c37\"><span class=\"c15 c3\">Co-requisites:</span></p>\n        </td>\n        <td class=\"c77\" colspan=\"4\">\n            <p class=\"c37\">\n                <span class=\"c2\">None</span>\n            </p>\n        </td>\n    </tr>\n    <tr class=\"c24\">\n        <td class=\"c127\" colspan=\"3\">\n            <p class=\"c37\">\n                <span class=\"c15 c3\">Designated Innovation Journey Course: </span>\n            </p>\n        </td>\n        <td class=\"c10\" colspan=\"8\">\n            <p class=\"c37\">\n                <span class=\"c2\"></span>\n            </p>\n        </td>\n    </tr>\n</table>\n<p class=\"c37 c27\"><span class=\"c2\"></span></p>\n\n<!-- Required Books/Readings and Suggested References -->\n<h1 class=\"c135\"><span class=\"c28 c11 c13\">Required Books/Readings:</span></h1>\n<p class=\"c36 c67 c27\"><span class=\"c2\"></span></p>\n<ul class=\"c31 lst-kix_list_4-0 start\">\n    <li class=\"c37 c67 c119 li-bullet-0\">\n        <span class=\"c2\"></span>\n    </li>\n</ul>\n\n\n\n<!-- Official Course Description and Learning Outcomes -->\n<h1 class=\"c53\">\n    <span class=\"c28 c11 c13\">Official Course Description:</span>\n</h1>\n<p class=\"c121\">\n      <span class=\"c2\">Students will survey and apply contemporary techniques used in analyzing and modeling information requirements. Requirements will be elicited in a variety of domains and abstracted at conceptual, logical, and physical levels of detail.</span>\n</p>\n<p class=\"c121 c27\"><span class=\"c2\"></span></p>\n<h1 class=\"c102\">\n    <span class=\"c28 c11 c13\">Course Learning Outcomes:</span>\n</h1>\n<p class=\"c139\">\n    <span class=\"c2\">At the end of this course, a student will be able to:</span>\n</p>\n<div class=\"c36\"></div>\n<p class=\"c27 c36\"><span class=\"c2\"></span></p>\n<h1 class=\"c102\">\n    <span class=\"c114\">Innovation Outcomes (if applicable):</span>\n</h1>\n<p class=\"c37 c60 c27\"><span class=\"c2\"></span></p>\n<table class=\"c128\">\n    <tr class=\"c24\">\n        <td class=\"c21 c59\">\n            <p class=\"c37 c60\"><span class=\"c2\">Innovation Outcome</span></p>\n        </td>\n        <td class=\"c59 c118\">\n            <p class=\"c37 c60\"><span class=\"c2\">Associated CLO</span></p>\n        </td>\n        <td class=\"c39\">\n            <p class=\"c37 c60\"><span class=\"c2\">Assessment Method</span></p>\n        </td>\n    </tr>\n    <tr class=\"c24\">\n        <td class=\"c21\">\n            <p class=\"c37 c60\"><span class=\"c2\">(CLO from innovation course material)</span></p>\n        </td>\n        <td class=\"c118\">\n            <p class=\"c37 c60\"><span class=\"c2\">(Associated CLO from list above)</span></p>\n        </td>\n        <td class=\"c52\">\n            <p class=\"c37 c60\">\n                <span class=\"c2\">(Map to assessments)</span>\n            </p>\n            <p class=\"c37 c60\">\n                <span class=\"c2\">Needs to be specific. For example, it could be a particular section of a report</span>\n            </p>\n        </td>\n    </tr>\n</table>\n<p class=\"c37 c27\"><span class=\"c2\"></span></p>\n<p class=\"c37\" id=\"h.gjdgxs\">\n    <span class=\"c11\">Mapping of CLOs to PLOs:</span>\n</p>\n<p class=\"c37\" id=\"h.7ogsur5kbn0l\">\n      <span class=\"c13 c78\">\n        Please refer to the table below to see the mapping of the Course Learning Outcomes to the Program Learning Outcomes:&nbsp;&#8203;\n      </span>\n</p>\n<p class=\"c37 c27\"><span class=\"c2\"></span></p>\n<p class=\"c37\">\n    <span class=\"c11\">CLOs-PLOs Mapping Table</span>\n</p>\n<table class=\"c20\">\n    <tr class=\"c24\">\n        <td style=\"border:1px solid #000; padding: 6px 8px; width: 40px; text-align: center; font-weight: 700;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; font-weight: 700;\">\n            <span class=\"c15 c3\">ISTE 430: Information Requirements Modeling</span>\n        </td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center; font-weight: 700;\">a</td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center; font-weight: 700;\">b</td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center; font-weight: 700;\">c</td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center; font-weight: 700;\">d</td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center; font-weight: 700;\">e</td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center; font-weight: 700;\">f</td>\n    </tr>\n    <tr class=\"c24\">\n        <td style=\"border:1px solid #000; padding: 6px 8px; width: 40px; text-align: center;\">1</td>\n        <td style=\"border:1px solid #000; padding: 6px 8px;\">\n            <span class=\"c2\">\n                <span>Prepare a requirements document, containing both text and models that can be used to implement a relational DBMS.</span>\n            </span>\n        </td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\">X</td>\n    </tr>\n    <tr class=\"c24\">\n        <td style=\"border:1px solid #000; padding: 6px 8px; width: 40px; text-align: center;\">2</td>\n        <td style=\"border:1px solid #000; padding: 6px 8px;\">\n            <span class=\"c2\">\n                <span>Compare and contrast the conceptual, logical and physical modeling processes and state the relationship among them.</span>\n            </span>\n        </td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\">X</td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\">X</td>\n    </tr>\n    <tr class=\"c24\">\n        <td style=\"border:1px solid #000; padding: 6px 8px; width: 40px; text-align: center;\">3</td>\n        <td style=\"border:1px solid #000; padding: 6px 8px;\">\n            <span class=\"c2\">\n                <span>Apply dataflow Apply dataflow diagramming, entity-relationship modeling, and state process modeling techniques to requirements analysis.</span>\n            </span>\n        </td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\">X</td>\n    </tr>\n    <tr class=\"c24\">\n        <td style=\"border:1px solid #000; padding: 6px 8px; width: 40px; text-align: center;\">4</td>\n        <td style=\"border:1px solid #000; padding: 6px 8px;\">\n            <span class=\"c2\">\n                <span>Identify, model, and explain valid business rules and identify appropriate attribute domains and constraints.</span>\n            </span>\n        </td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\">X</td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n    </tr>\n    <tr class=\"c24\">\n        <td style=\"border:1px solid #000; padding: 6px 8px; width: 40px; text-align: center;\">5</td>\n        <td style=\"border:1px solid #000; padding: 6px 8px;\">\n            <span class=\"c2\">\n                <span>Apply advanced normalization techniques to a relational model.</span>\n            </span>\n        </td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\">X</td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n        <td style=\"border:1px solid #000; padding: 6px 8px; text-align: center;\"></td>\n    </tr>\n</table>\n<p class=\"c37 c27\"><span class=\"c2\"></span></p>\n<p class=\"c37\">\n    <span class=\"c11\">Program Learning Outcomes:</span>\n</p>\n<div>\n    <table style=\"width: 100%; border-collapse: collapse;\">\n        <tr>\n            <td style=\"width: 52px; vertical-align: top; padding: 0 8px 4px 20px;\">\n                <span class=\"c2\">a)</span>\n            </td>\n            <td style=\"vertical-align: top; padding: 0 0 4px 0;\">\n                <span class=\"c2\">Analyze a complex computing problem and to apply principles of computing and other relevant disciplines to identify solutions.</span>\n            </td>\n        </tr>\n        <tr>\n            <td style=\"width: 52px; vertical-align: top; padding: 0 8px 4px 20px;\">\n                <span class=\"c2\">b)</span>\n            </td>\n            <td style=\"vertical-align: top; padding: 0 0 4px 0;\">\n                <span class=\"c2\">Design, implement, and evaluate a computing-based solution to meet a given set of computing requirements in the context of the program’s disciplines.</span>\n            </td>\n        </tr>\n        <tr>\n            <td style=\"width: 52px; vertical-align: top; padding: 0 8px 4px 20px;\">\n                <span class=\"c2\">c)</span>\n            </td>\n            <td style=\"vertical-align: top; padding: 0 0 4px 0;\">\n                <span class=\"c2\">Communicate effectively in a variety of professional contexts.</span>\n            </td>\n        </tr>\n        <tr>\n            <td style=\"width: 52px; vertical-align: top; padding: 0 8px 4px 20px;\">\n                <span class=\"c2\">d)</span>\n            </td>\n            <td style=\"vertical-align: top; padding: 0 0 4px 0;\">\n                <span class=\"c2\">Recognize professional responsibilities and make informed judgments in computing practice based on legal and ethical principles.</span>\n            </td>\n        </tr>\n        <tr>\n            <td style=\"width: 52px; vertical-align: top; padding: 0 8px 4px 20px;\">\n                <span class=\"c2\">e)</span>\n            </td>\n            <td style=\"vertical-align: top; padding: 0 0 4px 0;\">\n                <span class=\"c2\">Function effectively as a member or leader of a team engaged in activities appropriate to the program’s discipline.</span>\n            </td>\n        </tr>\n        <tr>\n            <td style=\"width: 52px; vertical-align: top; padding: 0 8px 4px 20px;\">\n                <span class=\"c2\">f)</span>\n            </td>\n            <td style=\"vertical-align: top; padding: 0 0 4px 0;\">\n                <span class=\"c2\">Identify and analyze user needs and to take them into account in the selection, creation, integration, evaluation, and administration of computing-based systems.</span>\n            </td>\n        </tr>\n    </table>\n</div>\n\n<p class=\"c37 c27\"><span class=\"c2\"></span></p>\n\n<!-- Teaching & Learning Methodologies -->\n<p class=\"c60 c97\">\n    <span class=\"c28 c11 c13\">Teaching &amp; Learning Methodologies:</span>\n</p>\n<p class=\"c102 c75 c110\">\n      <span class=\"c2\">In Person</span>\n</p>\n<p class=\"c102 c75 c110\">\n      <span class=\"c2\"></span>\n</p>\n<p class=\"c102 c75 c110\">\n    <span class=\"c3\"></span>\n    <span class=\"c13\"></span>\n</p>\n<p class=\"c102 c75 c110\">\n    <span class=\"c3\"></span>\n    <span class=\"c13\">\n\n      </span>\n</p>\n<p class=\"c37\">\n    <br>\n    <span class=\"c114\">Grading Scheme (please edit as per the course)</span>\n    <br>\n</p>\n\n<!-- Grading Scheme Table (static in this example) -->\n<table class=\"c20\">\n    <tr class=\"c24\">\n        <td class=\"c18\">\n            <p class=\"c37\"><span class=\"c87 c3\">Excellent</span></p>\n        </td>\n        <td class=\"c89\">\n            <p class=\"c37\"><span class=\"c87 c3\">Good</span></p>\n        </td>\n        <td class=\"c18\">\n            <p class=\"c37\"><span class=\"c3 c87\">Satisfactory</span></p>\n        </td>\n        <td class=\"c18\">\n            <p class=\"c37\"><span class=\"c87 c3\">Minimal Pass</span></p>\n        </td>\n        <td class=\"c89\">\n            <p class=\"c37\"><span class=\"c87 c3\">Fail</span></p>\n        </td>\n    </tr>\n    <tr class=\"c24\">\n        <td class=\"c18 c103\">\n            <p class=\"c37\"><span class=\"c5\">&nbsp; &nbsp; &nbsp; &nbsp;</span></p>\n        </td>\n        <td class=\"c89\">\n            <p class=\"c37\"><span class=\"c5\">B+ 87-89.99</span></p>\n        </td>\n        <td class=\"c18\">\n            <p class=\"c37\"><span class=\"c5\">C+ 77-79.99</span></p>\n        </td>\n        <td class=\"c18\">\n            <p class=\"c37\"><span class=\"c5\">D &nbsp; 60-69.99</span></p>\n        </td>\n        <td class=\"c89\">\n            <p class=\"c37\"><span class=\"c5\">F &nbsp; 0-59.99</span></p>\n        </td>\n    </tr>\n    <tr class=\"c24\">\n        <td class=\"c18\">\n            <p class=\"c37\"><span class=\"c5\">A &nbsp; 94-100</span></p>\n        </td>\n        <td class=\"c89\">\n            <p class=\"c37\"><span class=\"c5\">B &nbsp; 83-86.99</span></p>\n        </td>\n        <td class=\"c18\">\n            <p class=\"c37\"><span class=\"c5\">C &nbsp; 73-76.99</span></p>\n        </td>\n        <td class=\"c18 c103\">\n            <p class=\"c37 c27\"><span class=\"c5\"></span></p>\n        </td>\n        <td class=\"c89 c103\">\n            <p class=\"c37 c27\"><span class=\"c5\"></span></p>\n        </td>\n    </tr>\n    <tr class=\"c24\">\n        <td class=\"c18\">\n            <p class=\"c37\"><span class=\"c5\">A- &nbsp;90-93.99</span></p>\n        </td>\n        <td class=\"c89\">\n            <p class=\"c37\"><span class=\"c5\">B- &nbsp;80-82.99</span></p>\n        </td>\n        <td class=\"c18\">\n            <p class=\"c37\"><span class=\"c5\">C- &nbsp;70-72.99</span></p>\n        </td>\n        <td class=\"c18 c103\">\n            <p class=\"c37 c27\"><span class=\"c5\"></span></p>\n        </td>\n        <td class=\"c89 c103\">\n            <p class=\"c37 c27\"><span class=\"c5\"></span></p>\n        </td>\n    </tr>\n</table>\n\n<!-- Coursework and Distribution (with a loop for assessments) -->\n<h1 class=\"c97 c60 c140\">\n    <span class=\"c114\">Coursework and Distribution </span>\n    <span class=\"c50\">(please edit as per the course)</span>\n    <span class=\"c28 c11 c13\">:</span>\n</h1>\n<p class=\"c37 c86 c60\">\n      <span class=\"c2\"></span>\n</p>\n<table class=\"c134\">\n    <tr class=\"c82\">\n        <td class=\"c99\">\n            <p class=\"c27 c33\"><span class=\"c2\"></span></p>\n            <table class=\"c107\">\n                <tr class=\"c109\">\n                    <td class=\"c57 c59\">\n                        <p class=\"c53 c60 c122\"><span class=\"c15 c3\">Assessment</span></p>\n                    </td>\n                    <td class=\"c47 c59\">\n                        <p class=\"c14\"><span class=\"c15 c3\">CLO Mapping</span></p>\n                    </td>\n                    <td class=\"c44 c59\">\n                        <p class=\"c53 c60 c101\"><span class=\"c15 c3\">Weight</span></p>\n                    </td>\n                </tr>\n                <!-- Loop through each assessment -->\n                \n                <tr class=\"c93\">\n                    <td class=\"c131\" colspan=\"2\">\n                        <p class=\"c32\"><span class=\"c15 c3\">Total</span></p>\n                    </td>\n                    <td class=\"c44\">\n                        <p class=\"c32\"><span class=\"c15 c3\">100%</span></p>\n                    </td>\n                </tr>\n            </table>\n            <p class=\"c27 c41\"><span class=\"c2\"></span></p>\n        </td>\n    </tr>\n</table>\n\n<!-- Description of Assessments -->\n<h1 class=\"c102\">\n    <span class=\"c28 c11 c13\">Description of Assessments: </span>\n</h1>\n<!-- Category descriptions rendered from the service -->\n\n\n<p class=\"c37 c27 c49\"><span class=\"c2\"></span></p>\n<p class=\"c53 c49\">\n      <span class=\"c3\"></span>\n    <span class=\"c13\"></span>\n</p>\n<p class=\"c53 c49\">\n      <span style=\"overflow: hidden; display: inline-block; width: 46.00px; height: 3.33px;\">\n        <img alt=\"\" src=\"../static/images/image1.png\" style=\"width