->\n        <td class=\"c51\">\n            <h1 class=\"c23\">\n        \n            </h1>\n        </td>\n    </tr>\n    <tr>\n        <!-- Week column: display the key (e.g., \"Week 1\") -->\n        <td class=\"c30\">\n            <h1 class=\"c23\">Week 12</h1>\n        </td>\n\n        <!-- Topic column: intentionally kept as a fixed placeholder. -->\n        <td class=\"c1\">\n            <h1 class=\"c23\">N/A</h1>\n        </td>\n\n        <!-- Readings column:\n             Your received Assessment objects do not include readings;\n             you can either add them to your data model or leave this as a placeholder -->\n        <td class=\"c6\">\n            <h1 class=\"c23\">No reading yet</h1>\n        </td>\n\n        <!-- Assessment column: list all assessment names for the week.\n             You can either join them or use a nested loop. Here’s one method using a nested loop. -->\n        <td class=\"c51\">\n            <h1 class=\"c23\">\n        \n            </h1>\n        </td>\n    </tr>\n    <tr>\n        <!-- Week column: display the key (e.g., \"Week 1\") -->\n        <td class=\"c30\">\n            <h1 class=\"c23\">Week 13</h1>\n        </td>\n\n        <!-- Topic column: intentionally kept as a fixed placeholder. -->\n        <td class=\"c1\">\n            <h1 class=\"c23\">N/A</h1>\n        </td>\n\n        <!-- Readings column:\n             Your received Assessment objects do not include readings;\n             you can either add them to your data model or leave this as a placeholder -->\n        <td class=\"c6\">\n            <h1 class=\"c23\">No reading yet</h1>\n        </td>\n\n        <!-- Assessment column: list all assessment names for the week.\n             You can either join them or use a nested loop. Here’s one method using a nested loop. -->\n        <td class=\"c51\">\n            <h1 class=\"c23\">\n        <span>Project</span>\n            </h1>\n        </td>\n    </tr>\n    <tr>\n        <!-- Week column: display the key (e.g., \"Week 1\") -->\n        <td class=\"c30\">\n            <h1 class=\"c23\">Week 14</h1>\n        </td>\n\n        <!-- Topic column: intentionally kept as a fixed placeholder. -->\n        <td class=\"c1\">\n            <h1 class=\"c23\">N/A</h1>\n        </td>\n\n        <!-- Readings column:\n             Your received Assessment objects do not include readings;\n             you can either add them to your data model or leave this as a placeholder -->\n        <td class=\"c6\">\n            <h1 class=\"c23\">No reading yet</h1>\n        </td>\n\n        <!-- Assessment column: list all assessment names for the week.\n             You can either join them or use a nested loop. Here’s one method using a nested loop. -->\n        <td class=\"c51\">\n            <h1 class=\"c23\">\n        <span>Final</span>\n            </h1>\n        </td>\n    </tr>\n    </tbody>\n</table>\n    <tr class=\"c138\">\n        <td class=\"c30 c59\">\n            <h1 class=\"c12\"><span class=\"c2\"></span></h1>\n        </td>\n        <td class=\"c59 c98\" colspan=\"3\">\n            <h1 class=\"c63\">\n                <span class=\"c34\"></span>\n            </h1>\n        </td>\n    </tr>\n</table>\n<h1 class=\"c12\"><span class=\"c28 c11 c13\"></span></h1>\n\n<!-- Course Policies and Attendance -->\n<h1 class=\"c23 c60\">\n    <span class=\"c28 c11 c13\">Course Policies:</span>\n</h1>\n<p class=\"c37 c60\">\n    <span class=\"c45 c43\">Classroom conduct</span>\n</p>\n<ul class=\"c31 lst-kix_list_1-0 start\">\n    <li class=\"c53 c119 c60 li-bullet-0\">\n        <span class=\"c13\">\n          The rules of decorum apply in class: be respectful of me and of peers, ask productive questions, make appropriate and helpful observations…\n        </span>\n    </li>\n    <li class=\"c58 li-bullet-0\">\n        <span class=\"c13\">\n          Electronic devices—mobiles, tablets, and laptops—must be off and put away during class unless used for a specific activity.\n        </span>\n    </li>\n    <li class=\"c58 li-bullet-0\">\n        <span class=\"c13\">\n          No naps, no snacks. If you are too tired or hungry, take the absence.\n        </span>\n    </li>\n    <li class=\"c94 li-bullet-0\">\n        <span class=\"c2\">\n          If you work consistently and conscientiously, I will “round up” the “ones” before posting final grades.\n        </span>\n    </li>\n</ul>\n<p class=\"c37\">\n    <span class=\"c2\">Infractions of these rules of conduct will negatively impact your final grade.</span>\n</p>\n<p class=\"c37 c60\">\n    <span class=\"c71 c45 c74 c43 c13 c108\">Course Management</span>\n</p>\n<ul class=\"c31 lst-kix_list_1-0\">\n    <li class=\"c58 c60 li-bullet-0\">\n        <span class=\"c13\">\n          You are responsible for knowing what’s due and when by referring to the syllabus.\n        </span>\n    </li>\n    <li class=\"c58 li-bullet-0\">\n        <span class=\"c13\">\n          Coursework is cumulative—complete them conscientiously.\n        </span>\n    </li>\n    <li class=\"c58 li-bullet-0\">\n        <span class=\"c3\">Type-written work</span><span class=\"c2\"> must be turned in through MyCourses and in hard copy by the fixed deadlines.</span>\n    </li>\n    <li class=\"c58 li-bullet-0\">\n        <span class=\"c13\">\n          Individual work must be your own.\n        </span>\n    </li>\n    <li class=\"c58 li-bullet-0\">\n        <span class=\"c3\">Late work</span><span class=\"c2\"> will be deducted 10% every calendar day without exception.</span>\n    </li>\n    <li class=\"c94 li-bullet-0\">\n        <span class=\"c3\">Things may change</span> <span class=\"c13\">but such changes will be communicated in writing.</span>\n    </li>\n</ul>\n<p class=\"c37 c60\">\n    <span class=\"c45 c43\">Attendance Policy:</span>\n</p>\n<p class=\"c37 c60\">\n    <span class=\"c3 c15\">Please select one of these two options:</span>\n</p>\n<!-- Show one of the two options based on a Boolean variable -->\n\n\n<ul class=\"c31 lst-kix_list_5-0\">\n    <li class=\"c53 c133 li-bullet-0\">\n        <span class=\"c15 c3\">Attendance is not mandatory for this course</span>\n    </li>\n</ul>\n<p class=\"c37 c100\">\n      <span class=\"c71 c74 c43 c13 c96\">\n        (If you chose not to apply the attendance policy, then you must clearly state the following here in the syllabus and attendance record is not applicable in this case.)\n      </span>\n</p>\n<p class=\"c53 c83\">\n      <span class=\"c2\"></span>\n</p>\n<p class=\"c53 c83\">\n    <span class=\"c2\">Refer to university policy 3.1.14-B.</span>\n</p>\n\n<!-- RIT Dubai Honor Principles and Academic Integrity -->\n<p class=\"c23\">\n    <span class=\"c28 c11 c13\">RIT Dubai Honor Principles:</span>\n</p>\n<p class=\"c53 c65\">\n      <span class=\"c13 c125\">\n        Refer to Policy 5.1.1- RIT Dubai Honor Code in the Student Handbook\n      </span>\n</p>\n<h1 class=\"c37\">\n    <span class=\"c28 c11 c13\">Academic Integrity:</span>\n</h1>\n<p class=\"c53 c70\">\n      <span class=\"c125\"></span>\n</p>\n<p class=\"c53 c70\">\n      <span></span>\n</p>\n<p class=\"c53 c70\">\n      <span></span>\n</p>\n<p class=\"c53 c70\">\n      <span></span>\n</p>\n<p class=\"c53 c70\">\n    <span class=\"c28 c50 c13\">Procedures for handling Academic Dishonesty:</span>\n</p>\n<p class=\"c53 c70\" id=\"h.30j0zll\">\n      <span class=\"c125\"></span>\n</p>\n<p class=\"c27 c105\"><span class=\"c0\"></span></p>\n</body>\n','2026-05-01',0x01,30),
